import { useForm } from '@dreadnought/react/logic';
import { Form, FormField, Input, Button } from '@dreadnought/ui/react';
export function Example() {
  const form = useForm({ initialValues: { name: '' } });
  const name = form.field('name');
  return <Form form={form} onFinish={values => { console.log(values.name); }}>
    <FormField label="Имя" error={name.error}>{props =>
      <Input {...props} value={name.value}
        onChange={event => name.setValue(event.target.value)}
        onBlur={name.onBlur} />}
    </FormField>
    <Button type="submit">Сохранить</Button>
  </Form>;
}
